create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,owner_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz default now());
create table if not exists public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null default 'member',created_at timestamptz default now(),primary key(workspace_id,user_id));
create table if not exists public.investment_profiles(id uuid primary key default gen_random_uuid(),workspace_id uuid unique references public.workspaces(id) on delete cascade,sectors text[] default '{}',industries text[] default '{}',stages text[] default '{}',check_size_min numeric,check_size_max numeric,geographies text[] default '{}',business_models text[] default '{}',founder_preferences text,revenue_requirements text,traction_requirements text,risk_tolerance text,thesis text,excluded_industries text[] default '{}',negative_keywords text[] default '{}',positive_keywords text[] default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.settings(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,key text not null,value jsonb not null default '{}',created_at timestamptz default now(),updated_at timestamptz default now(),unique(workspace_id,key));
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,name text not null,website text,industry text,stage text,location text,funding numeric,revenue numeric,employees integer,status text default 'watching',research text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.people(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,name text not null,role text,company_id uuid references public.companies(id) on delete set null,source text,score numeric,status text default 'new',ai_summary text,notes text,last_interaction timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.opportunities(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,company_id uuid references public.companies(id) on delete set null,person_id uuid references public.people(id) on delete set null,title text not null,industry text,stage text,funding_target numeric,location text,website text,score numeric default 0,confidence numeric default 0,investment_fit numeric default 0,founder_score numeric default 0,market_score numeric default 0,traction_score numeric default 0,timing_score numeric default 0,source_confidence numeric default 0,status text default 'new',why text,risks text,next_step text,next_follow_up timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.research_runs(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,query text not null,status text default 'running',started_at timestamptz default now(),completed_at timestamptz,summary text,error text);
create table if not exists public.research_sources(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,research_run_id uuid references public.research_runs(id) on delete cascade,title text,url text not null,source_date timestamptz,summary text,created_at timestamptz default now());
create table if not exists public.research_items(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,research_run_id uuid references public.research_runs(id) on delete cascade,title text not null,summary text,key_facts jsonb default '[]',ai_analysis text,entities jsonb default '{}',relevance_score numeric default 0,created_at timestamptz default now());
create table if not exists public.facebook_connections(id uuid primary key default gen_random_uuid(),workspace_id uuid unique references public.workspaces(id) on delete cascade,provider text default 'meta',account_name text,status text default 'not_connected',access_token_encrypted text,token_expires_at timestamptz,permissions jsonb default '[]',last_sync timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.facebook_pages(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,connection_id uuid references public.facebook_connections(id) on delete cascade,page_id text,name text,category text,created_at timestamptz default now());
create table if not exists public.facebook_posts(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,page_id uuid references public.facebook_pages(id) on delete set null,external_id text,author_name text,content text,permalink text,published_at timestamptz,relevance_score numeric default 0,classification text,analyzed_at timestamptz,created_at timestamptz default now(),unique(workspace_id,external_id));
create table if not exists public.facebook_comments(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,post_id uuid references public.facebook_posts(id) on delete cascade,external_id text,author_name text,content text,classification text,confidence numeric default 0,investment_signals jsonb default '{}',reply_draft text,replied_at timestamptz,created_at timestamptz default now(),unique(workspace_id,external_id));
create table if not exists public.facebook_messages(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,external_id text,person_id uuid references public.people(id) on delete set null,content text,direction text,classification text,ai_summary text,reply_draft text,created_at timestamptz default now());
create table if not exists public.content_drafts(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,title text,body text not null,source text,ai_confidence numeric,status text default 'draft',scheduled_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.scheduled_posts(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,draft_id uuid references public.content_drafts(id) on delete cascade,scheduled_at timestamptz not null,status text default 'scheduled',created_at timestamptz default now());
create table if not exists public.published_posts(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,draft_id uuid references public.content_drafts(id) on delete set null,external_id text,published_at timestamptz,permalink text,created_at timestamptz default now());
create table if not exists public.approval_queue(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,entity_type text not null,entity_id uuid,reason text,proposed_action text,confidence numeric,source text,status text default 'pending',created_at timestamptz default now(),reviewed_at timestamptz);
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,title text not null,description text,status text default 'open',due_at timestamptz,opportunity_id uuid references public.opportunities(id) on delete set null,person_id uuid references public.people(id) on delete set null,created_at timestamptz default now());
create table if not exists public.notes(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,entity_type text,entity_id uuid,content text not null,created_at timestamptz default now());
create table if not exists public.automation_rules(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,name text not null,enabled boolean default false,trigger jsonb default '{}',conditions jsonb default '{}',actions jsonb default '[]',limits jsonb default '{}',cooldown_minutes integer default 0,approval_required boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.automation_runs(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,rule_id uuid references public.automation_rules(id) on delete cascade,status text,result jsonb default '{}',error text,started_at timestamptz default now(),completed_at timestamptz);
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,title text not null,body text,type text,read_at timestamptz,created_at timestamptz default now());
create table if not exists public.activity_logs(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,actor_type text default 'system',action text not null,entity_type text,entity_id uuid,result jsonb default '{}',error text,created_at timestamptz default now());
create table if not exists public.ai_generations(id uuid primary key default gen_random_uuid(),workspace_id uuid references public.workspaces(id) on delete cascade,task text not null,model text,input jsonb default '{}',output jsonb default '{}',latency_ms integer,created_at timestamptz default now());
create index if not exists idx_workspace_created on public.opportunities(workspace_id,created_at desc);
create index if not exists idx_opportunity_status_score on public.opportunities(workspace_id,status,score desc);
create index if not exists idx_people_workspace on public.people(workspace_id,created_at desc);
create index if not exists idx_companies_workspace on public.companies(workspace_id,created_at desc);
create index if not exists idx_research_workspace on public.research_items(workspace_id,created_at desc);
create index if not exists idx_approval_status on public.approval_queue(workspace_id,status,created_at desc);
create index if not exists idx_activity_created on public.activity_logs(workspace_id,created_at desc);

do $$ declare t text; begin for t in select table_name from information_schema.tables where table_schema='public' and table_name in ('profiles','workspaces','workspace_members','investment_profiles','settings','companies','people','opportunities','research_runs','research_sources','research_items','facebook_connections','facebook_pages','facebook_posts','facebook_comments','facebook_messages','content_drafts','scheduled_posts','published_posts','approval_queue','tasks','notes','automation_rules','automation_runs','notifications','activity_logs','ai_generations') loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create or replace function public.is_workspace_member(wid uuid) returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=wid and wm.user_id=(select auth.uid())); $$;
create or replace function public.is_workspace_owner(wid uuid) returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.workspaces w where w.id=wid and w.owner_id=(select auth.uid())); $$;

do $$ declare t text; begin for t in select table_name from information_schema.tables where table_schema='public' and table_name in ('investment_profiles','settings','companies','people','opportunities','research_runs','research_sources','research_items','facebook_connections','facebook_pages','facebook_posts','facebook_comments','facebook_messages','content_drafts','scheduled_posts','published_posts','approval_queue','tasks','notes','automation_rules','automation_runs','notifications','activity_logs','ai_generations') loop execute format('drop policy if exists workspace_access on public.%I',t); execute format('create policy workspace_access on public.%I for all to authenticated using (public.is_workspace_member(workspace_id)) with check (public.is_workspace_member(workspace_id))',t); end loop; end $$;
drop policy if exists workspace_member_access on public.workspace_members;
create policy workspace_member_access on public.workspace_members for select to authenticated using (user_id=(select auth.uid()) or public.is_workspace_member(workspace_id));
drop policy if exists workspace_owner_access on public.workspaces;
create policy workspace_owner_access on public.workspaces for all to authenticated using (owner_id=(select auth.uid()) or public.is_workspace_member(id)) with check (owner_id=(select auth.uid()));
drop policy if exists profile_self_access on public.profiles;
create policy profile_self_access on public.profiles for all to authenticated using (id=(select auth.uid())) with check (id=(select auth.uid()));
